begin;
create extension if not exists pgtap with schema extensions;
select plan(26);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','97000000-0000-4000-8000-000000000001','authenticated','authenticated','invoice-owner@example.test','',now(),now(),now());
set local role authenticated;select set_config('request.jwt.claim.sub','97000000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"97000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.create_business('invoice-test','Invoice Test Legal','Invoice Test','sole_proprietorship','retail','{"city":"Manila"}');select set_config('test.ar_org',(select id::text from public.organizations where slug='invoice-test'),true);select set_config('test.ar_branch',(select id::text from public.branches where organization_id=current_setting('test.ar_org')::uuid and code='main'),true);
select is(public.can_business_permission(current_setting('test.ar_org')::uuid,'invoices.manage'),true,'Owner receives invoicing permissions');
select throws_ok($$select public.save_invoice(current_setting('test.ar_org')::uuid,null,current_setting('test.ar_branch')::uuid,gen_random_uuid(),current_date,current_date+30,'','[]',false)$$,'42501','Permission denied.','Invoice mutations require the enabled module');
select public.set_business_module_state(current_setting('test.ar_org')::uuid,'product_catalog',true,'{}');select public.set_business_module_state(current_setting('test.ar_org')::uuid,'inventory',true,'{}');select public.set_business_module_state(current_setting('test.ar_org')::uuid,'sales',true,'{}');select public.set_business_module_state(current_setting('test.ar_org')::uuid,'pos',true,'{}');select lives_ok($$select public.set_business_module_state(current_setting('test.ar_org')::uuid,'invoicing',true,'{"payment_terms_days":30}')$$,'Invoicing module activates with credit terms');
select set_config('test.ar_customer',public.save_sales_customer(current_setting('test.ar_org')::uuid,null,'Jose Cruz','09171234567','jose@example.test')::text,true);
select set_config('test.ar_product',public.save_catalog_product(current_setting('test.ar_org')::uuid,null,null,'product','Desk Lamp','',null,null,'piece',100,50,'inclusive',12,'active',false,'[{"name":"Default","sku":"LAMP-001","barcode":"4800000000003","attributes":{},"status":"active"}]','[]')::text,true);select set_config('test.ar_variant',(select id::text from public.product_variants where product_id=current_setting('test.ar_product')::uuid),true);select set_config('test.ar_location',(select id::text from public.inventory_locations where organization_id=current_setting('test.ar_org')::uuid),true);select set_config('test.ar_item',public.configure_inventory_item(current_setting('test.ar_org')::uuid,null,current_setting('test.ar_variant')::uuid,0,0,true)::text,true);select public.record_stock_movement(current_setting('test.ar_org')::uuid,current_setting('test.ar_item')::uuid,current_setting('test.ar_location')::uuid,'opening_balance',10,50,'Opening','ar-opening-001');
select set_config('test.ar_sale',public.save_pos_transaction(current_setting('test.ar_org')::uuid,null,current_setting('test.ar_branch')::uuid,current_setting('test.ar_location')::uuid,current_setting('test.ar_customer')::uuid,'completed','97000000-0000-4000-8000-000000000101',now(),('[{"productVariantId":"'||current_setting('test.ar_variant')||'","quantity":2,"discountAmount":0}]')::jsonb,'[{"method":"cash","amount":200,"reference":""}]')::text,true);
select set_config('test.ar_sale_invoice',public.create_invoice_from_sale(current_setting('test.ar_org')::uuid,current_setting('test.ar_sale')::uuid,current_date+30,true)::text,true);
select results_eq($$select source_type,source_id,status,total,tax_total,balance_due from public.invoices where id=current_setting('test.ar_sale_invoice')::uuid$$,$$select 'sale'::text,current_setting('test.ar_sale')::uuid,'issued'::text,200::numeric,21.4286::numeric,200::numeric$$,'Invoice generation preserves authoritative sale totals and tax');
select results_eq($$select total,tax_amount from public.invoice_lines where invoice_id=current_setting('test.ar_sale_invoice')::uuid$$,$$select 200::numeric,21.4286::numeric$$,'Sale invoice lines preserve source totals');
select set_config('test.ar_old',public.save_invoice(current_setting('test.ar_org')::uuid,null,current_setting('test.ar_branch')::uuid,current_setting('test.ar_customer')::uuid,current_date-120,current_date-100,'Old receivable','[{"description":"Consulting","productVariantId":"","sku":"","unit":"service","quantity":1,"unitPrice":1000,"discountAmount":0,"taxRate":0}]',true)::text,true);
select set_config('test.ar_current',public.save_invoice(current_setting('test.ar_org')::uuid,null,current_setting('test.ar_branch')::uuid,current_setting('test.ar_customer')::uuid,current_date,current_date+30,'Current receivable','[{"description":"Support","productVariantId":"","sku":"","unit":"service","quantity":1,"unitPrice":500,"discountAmount":0,"taxRate":0}]',true)::text,true);
select results_eq($$select invoice_number from public.invoices where id=current_setting('test.ar_old')::uuid$$,$$select 'INV-'||extract(year from current_date)::integer||'-000002'$$,'Invoice numbers are sequential per Business and year');
select results_eq($$select outstanding_balance from public.sales_customers where id=current_setting('test.ar_customer')::uuid$$,$$select 1700::numeric$$,'Customer outstanding balance materializes open invoice balances');
select lives_ok($$select public.refresh_overdue_invoices(current_setting('test.ar_org')::uuid)$$,'Overdue invoice refresh runs safely');
select results_eq($$select status from public.invoices where id=current_setting('test.ar_old')::uuid$$,$$select 'overdue'::text$$,'Past-due open invoice becomes overdue');
select results_eq($$select (public.receivables_dashboard(current_setting('test.ar_org')::uuid)->>'totalReceivables')::numeric,(public.receivables_dashboard(current_setting('test.ar_org')::uuid)->>'overdueAmount')::numeric$$,$$select 1700::numeric,1000::numeric$$,'Dashboard returns total and overdue receivables');
select results_eq($$select (public.receivables_dashboard(current_setting('test.ar_org')::uuid)->'aging'->>'current')::numeric,(public.receivables_dashboard(current_setting('test.ar_org')::uuid)->'aging'->>'90+')::numeric$$,$$select 700::numeric,1000::numeric$$,'Aging separates current and 90+ balances');
select results_eq($$select public.receivables_dashboard(current_setting('test.ar_org')::uuid)->'topDebtors'->0->>'customerName'$$,$$select 'Jose Cruz'::text$$,'Dashboard ranks top debtors');
select set_config('test.ar_payment1',public.record_ar_payment(current_setting('test.ar_org')::uuid,current_setting('test.ar_branch')::uuid,current_setting('test.ar_customer')::uuid,current_date,'bank_transfer','BANK-001',400,('[{"invoiceId":"'||current_setting('test.ar_old')||'","amount":400}]')::jsonb,'ar-payment-001')::text,true);
select results_eq($$select status,amount_paid,balance_due from public.invoices where id=current_setting('test.ar_old')::uuid$$,$$select 'partially_paid'::text,400::numeric,600::numeric$$,'Partial payment updates invoice balances atomically');
select results_eq($$select amount,unapplied_amount from public.ar_payments where id=current_setting('test.ar_payment1')::uuid$$,$$select 400::numeric,0::numeric$$,'Payment allocation records applied and unapplied amounts');
select results_eq($$select outstanding_balance from public.sales_customers where id=current_setting('test.ar_customer')::uuid$$,$$select 1300::numeric$$,'Partial payment updates customer balance');
select results_eq($$select public.record_ar_payment(current_setting('test.ar_org')::uuid,current_setting('test.ar_branch')::uuid,current_setting('test.ar_customer')::uuid,current_date,'bank_transfer','REPLAY',400,('[{"invoiceId":"'||current_setting('test.ar_old')||'","amount":400}]')::jsonb,'ar-payment-001')$$,$$select current_setting('test.ar_payment1')::uuid$$,'Payment idempotency returns the original payment');
select results_eq($$select count(*)from public.payment_allocations where payment_id=current_setting('test.ar_payment1')::uuid$$,$$select 1::bigint$$,'Payment replay cannot duplicate allocations');
select throws_ok($$select public.record_ar_payment(current_setting('test.ar_org')::uuid,current_setting('test.ar_branch')::uuid,current_setting('test.ar_customer')::uuid,current_date,'cash','OVER',600,('[{"invoiceId":"'||current_setting('test.ar_current')||'","amount":600}]')::jsonb,'ar-payment-over')$$,'P0001','Invalid payment allocation.','Over-allocation is rejected');
select results_eq($$select count(*)from public.ar_payments where idempotency_key='ar-payment-over'$$,$$select 0::bigint$$,'Failed allocation leaves no partial payment');
select set_config('test.ar_payment2',public.record_ar_payment(current_setting('test.ar_org')::uuid,current_setting('test.ar_branch')::uuid,current_setting('test.ar_customer')::uuid,current_date,'cash','CASH-001',650,('[{"invoiceId":"'||current_setting('test.ar_old')||'","amount":600}]')::jsonb,'ar-payment-002')::text,true);
select results_eq($$select status,balance_due from public.invoices where id=current_setting('test.ar_old')::uuid$$,$$select 'paid'::text,0::numeric$$,'Final allocation marks the invoice paid');
select results_eq($$select unapplied_amount from public.ar_payments where id=current_setting('test.ar_payment2')::uuid$$,$$select 50::numeric$$,'Payment can retain unapplied customer credit');
select lives_ok($$select public.cancel_invoice(current_setting('test.ar_org')::uuid,current_setting('test.ar_current')::uuid,'Customer requested cancellation')$$,'Unpaid issued invoice can be cancelled');
select results_eq($$select status,balance_due from public.invoices where id=current_setting('test.ar_current')::uuid$$,$$select 'cancelled'::text,0::numeric$$,'Cancellation removes invoice balance');
select results_eq($$select outstanding_balance from public.sales_customers where id=current_setting('test.ar_customer')::uuid$$,$$select 200::numeric$$,'Customer balance excludes paid and cancelled invoices');
reset role;
select results_eq($$select count(*)from public.accounting_integration_events where organization_id=current_setting('test.ar_org')::uuid and event_type in('invoice.issued','payment.recorded','invoice.cancelled')$$,$$select 6::bigint$$,'Accounting outbox captures invoice, payment, and cancellation events idempotently');
set local role authenticated;
select throws_ok($$update public.payment_allocations set amount=1 where payment_id=current_setting('test.ar_payment1')::uuid$$,'42501','permission denied for table payment_allocations','Payment allocations are immutable to clients');
select * from finish();rollback;
